const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to today's short lecture on everyday study habits and sleep patterns.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.54625},{"speaker":"A","text":"Many students struggle because they try to study for hours without taking proper breaks.","position":2,"audioStartSeconds":5.74625,"audioEndSeconds":11.094958333333333},{"speaker":"A","text":"If you plan your schedule carefully, you can achieve much better academic results.","position":3,"audioStartSeconds":11.294958333333334,"audioEndSeconds":16.526916666666665},{"speaker":"A","text":"Another major factor that affects student performance is the quality of nightly rest.","position":4,"audioStartSeconds":16.726916666666668,"audioEndSeconds":22.1135},{"speaker":"A","text":"When people stay up late reading books, their brains fail to process information properly.","position":5,"audioStartSeconds":22.3135,"audioEndSeconds":27.8805},{"speaker":"A","text":"For example, imagine a student reviewing complex grammar rules just before midnight.","position":6,"audioStartSeconds":28.0805,"audioEndSeconds":33.57020833333333},{"speaker":"A","text":"Although they spend two hours reviewing, they will likely forget most of it by morning.","position":7,"audioStartSeconds":33.770208333333336,"audioEndSeconds":39.01504166666667},{"speaker":"A","text":"Our teachers always suggest turning off digital screens at least one hour before bedtime.","position":8,"audioStartSeconds":39.215041666666664,"audioEndSeconds":44.96245833333333},{"speaker":"A","text":"This simple habit allows your mind to relax and prepares your body for deep sleep.","position":9,"audioStartSeconds":45.16245833333333,"audioEndSeconds":50.342875},{"speaker":"A","text":"Furthermore, keeping a tidy study desk helps reduce daily stress significantly.","position":10,"audioStartSeconds":50.542875,"audioEndSeconds":56.045458333333336},{"speaker":"A","text":"If your workspace is messy, you will spend valuable time looking for lost pens.","position":11,"audioStartSeconds":56.24545833333333,"audioEndSeconds":61.516083333333334},{"speaker":"A","text":"Organising your notebooks every evening makes morning revision much faster and easier.","position":12,"audioStartSeconds":61.71608333333333,"audioEndSeconds":67.28191666666666},{"speaker":"A","text":"Students should also try to eat fresh fruit instead of sugary snacks during revision.","position":13,"audioStartSeconds":67.48191666666666,"audioEndSeconds":72.818125},{"speaker":"A","text":"Healthy foods provide steady energy while sugary snacks cause sudden tiredness later.","position":14,"audioStartSeconds":73.018125,"audioEndSeconds":78.63670833333333},{"speaker":"A","text":"Please remember that small daily changes will lead to lasting improvements over time.","position":15,"audioStartSeconds":78.83670833333333,"audioEndSeconds":84.18504166666666}],"questions":[{"prompt":"Main topic of today's lecture: ______","answer":"study habits","evidenceSentence":1,"evidence":"everyday study habits and sleep patterns","explanation":"Giảng viên giới thiệu chủ đề chính của bài giảng là thói quen học tập hàng ngày và giấc ngủ."},{"prompt":"Activity to avoid right before midnight: ______","answer":"grammar rules","evidenceSentence":6,"evidence":"reviewing complex grammar rules just before midnight","explanation":"Ví dụ nhắc đến việc ôn tập các quy tắc ngữ pháp phức tạp ngay trước nửa đêm."},{"prompt":"Recommended action regarding digital devices: ______","answer":"turning off","evidenceSentence":8,"evidence":"turning off digital screens at least one hour before bedtime","explanation":"Giảng viên đề nghị tắt màn hình kỹ thuật số ít nhất một giờ trước khi đi ngủ."},{"prompt":"Benefit of keeping a tidy study desk: ______","answer":"daily stress","evidenceSentence":10,"evidence":"keeping a tidy study desk helps reduce daily stress significantly","explanation":"Bàn học gọn gàng giúp giảm đáng kể căng thẳng hàng ngày."},{"prompt":"Alternative food choice during revision: ______","answer":"fresh fruit","evidenceSentence":13,"evidence":"try to eat fresh fruit instead of sugary snacks","explanation":"Học sinh nên ăn trái cây tươi thay vì đồ ăn vặt chứa đường."},{"prompt":"Result of small daily changes: ______","answer":"lasting improvements","evidenceSentence":15,"evidence":"small daily changes will lead to lasting improvements","explanation":"Những thay đổi nhỏ hàng ngày sẽ mang lại sự cải thiện lâu dài."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
